// Bits 0-1 select the two gradient axes; bits 2-3 select their signs.
static const unsigned char NoiseGradSelector[16] = {
    0, 4, 8, 12, 2, 6, 10, 14, 3, 7, 11, 15, 0, 4, 11, 15};

inline float GradFromHash(int hash, float dx, float dy, float dz) {
    unsigned char selector = NoiseGradSelector[hash & 15];
