inline float Clamp(float v, float low, float high) { return v < low ? low : ((v > high) ? high : v); }

inline float SmoothStep(float low, float high, float value) {
    float v = Clamp((value - low) / (high - low), 0.f, 1.f);
    return v * v * (-2.f * v + 3.f);
}

inline int Floor2Int(float val) { return (int)floorf(val); }

// Bits 0-1 select the two gradient axes; bits 2-3 select their signs.
static const unsigned char NoiseGradSelector[16] = {
    0, 4, 8, 12, 2, 6, 10, 14, 3, 7, 11, 15, 0, 4, 11, 15};

inline float GradFromHash(int hash, float dx, float dy, float dz) {
    unsigned char selector = NoiseGradSelector[hash & 15];
    float u = (selector & 1) ? dy : dx;
    float v = (selector & 2) ? dz : dy;
    return ((selector & 4) ? -u : u) + ((selector & 8) ? -v : v);
}

inline float NoiseWeight(float t) {
    float t3 = t * t * t;
    float t4 = t3 * t;
    return 6.f * t4 * t - 15.f * t4 + 10.f * t3;
}

inline float Lerp(float t, float low, float high) { return (1.f - t) * low + t * high; }

static float Noise(float x, float y, float z) {
    // Compute noise cell coordinates and offsets
    int ix = Floor2Int(x), iy = Floor2Int(y), iz = Floor2Int(z);
    float dx = x - ix, dy = y - iy, dz = z - iz;

    // Wrap each permutation lookup explicitly instead of storing a duplicate table.
    ix &= (NOISE_PERM_SIZE - 1);
    iy &= (NOISE_PERM_SIZE - 1);
    iz &= (NOISE_PERM_SIZE - 1);
    int px0 = NoisePerm[ix];
    int px1 = NoisePerm[(ix + 1) & (NOISE_PERM_SIZE - 1)];
    int pxy00 = NoisePerm[(px0 + iy) & (NOISE_PERM_SIZE - 1)];
    int pxy10 = NoisePerm[(px1 + iy) & (NOISE_PERM_SIZE - 1)];
    int pxy01 = NoisePerm[(px0 + iy + 1) & (NOISE_PERM_SIZE - 1)];
    int pxy11 = NoisePerm[(px1 + iy + 1) & (NOISE_PERM_SIZE - 1)];

    float w000 = GradFromHash(NoisePerm[(pxy00 + iz) & (NOISE_PERM_SIZE - 1)], dx, dy, dz);
    float w100 = GradFromHash(NoisePerm[(pxy10 + iz) & (NOISE_PERM_SIZE - 1)], dx - 1, dy, dz);
    float w010 = GradFromHash(NoisePerm[(pxy01 + iz) & (NOISE_PERM_SIZE - 1)], dx, dy - 1, dz);
    float w110 = GradFromHash(NoisePerm[(pxy11 + iz) & (NOISE_PERM_SIZE - 1)], dx - 1, dy - 1, dz);
    float w001 = GradFromHash(NoisePerm[(pxy00 + iz + 1) & (NOISE_PERM_SIZE - 1)], dx, dy, dz - 1);
    float w101 = GradFromHash(NoisePerm[(pxy10 + iz + 1) & (NOISE_PERM_SIZE - 1)], dx - 1, dy, dz - 1);
    float w011 = GradFromHash(NoisePerm[(pxy01 + iz + 1) & (NOISE_PERM_SIZE - 1)], dx, dy - 1, dz - 1);
    float w111 = GradFromHash(NoisePerm[(pxy11 + iz + 1) & (NOISE_PERM_SIZE - 1)], dx - 1, dy - 1, dz - 1);

    // Compute trilinear interpolation of weights
    float wx = NoiseWeight(dx), wy = NoiseWeight(dy), wz = NoiseWeight(dz);
    float x00 = Lerp(wx, w000, w100);
    float x10 = Lerp(wx, w010, w110);
    float x01 = Lerp(wx, w001, w101);
    float x11 = Lerp(wx, w011, w111);
    float y0 = Lerp(wy, x00, x10);
    float y1 = Lerp(wy, x01, x11);
    return Lerp(wz, y0, y1);
}

static float Turbulence(float x, float y, float z, int octaves) {
    float omega = 0.6;

    float sum = 0., lambda = 1., o = 1.;
    for (int i = 0; i < octaves; ++i) {
        sum += fabsf(o * Noise(lambda * x, lambda * y, lambda * z));
        lambda *= 1.99f;
        o *= omega;
    }
    return sum * 0.5f;
}

void noise_serial(float x0, float y0, float x1, float y1, int width, int height, float output[]) {
    float dx = (x1 - x0) / width;
    float dy = (y1 - y0) / height;

    for (int j = 0; j < height; j++) {
        for (int i = 0; i < width; ++i) {
            float x = x0 + i * dx;
            float y = y0 + j * dy;

            int index = (j * width + i);
            output[index] = Turbulence(x, y, 0.6f, 8);
        }
    }
}
